```php
<?php
// Cuir in iúl an sonraí rochtana do Ríomhaire Windows
$domain = "seoirsean";
$computername = "seoirsean-PC";
$username = "admin";
$password = "admnpass";

// Foirmáid an sonraí don úsáid le húsáid le húsáid le húsáid
$credentials = new stdClass();
$credentials->domain = $domain;
$credentials->username = $username;
$credentials->password = $password;
$credentials->computername = $credentials->domain . "\\" . $computername;

// Táimid ag úsáid an móid chuig an ríomhaire Windows
$resource = $credentials->domain . "\\" . $credentials->computername . "\\" . $credentials->username;

// Cuir in iúl an tseanscáileán
$seanscáileán = "\\\\$resource\\C$";

// Táimid ag úsáid an scáileán
$handle = \com_createfile($seanscáileán);

// Cuir in iúl chomh maith an bhunús
$access = \FILE_SHARE_READ | \FILE_SHARE_WRITE | \FILE_SHARE_DELETE;

// Táimid ag úsáid an chuid
