Is féidir liom script a scríobh a thabharfadh cuntas airgeadais ar theideal don úsáideoch. Tá an script seo scríofa i gC, agus is féidir é a chur i ngearrdocht go háitiúil.

```c
#include <stdio.h>
#include <stdint.h>

// Struct to hold stock information
typedef struct {
    char name[50];
    int quantity;
    float price;
} Stock;

// Struct to hold account information
typedef struct {
    char name[50];
    float balance;
} Account;

// Function to add stock to account
void addStock(Account* account, Stock* stock, int quantity) {
    float cost = stock->price * quantity;
    account->balance += cost;
    printf("Stock %s added to account %s for %f\n", stock->name, account->name, cost);
}

// Function to sell stock
void sellStock(Account* account, Stock* stock, int quantity) {
    if (account->balance >= stock->price * quantity) {
        float revenue = stock->price * quantity;
        account->balance -= revenue;
        printf("Stock %s sold from account %s for %f\n", stock->name, account->name, revenue);
    } else {
        printf("Insufficient balance to sell %s\n", stock->name);
    }
}

// Function to display account information
void displayAccount(Account* account) {
    printf("Account Name: %s\n", account->name);
    printf("Balance: %f\n", account->balance);
}

int main() {
    // Initialize account
    Account account;
    strcpy(account.name, "John Doe");
    account.balance = 1000.0f;

    // Initialize stock
    Stock stock1;
    strcpy(stock1.name, "Apple");
    stock1.quantity = 10;
    stock1.price = 5.0f;

    Stock stock2;
    strcpy(stock2.name, "Banana");
    stock2.quantity = 20;
    stock2.price = 3.0f;

    // Add stock to account
    addStock(&account, &stock1, 5);
    addStock(&account, &stock2, 10);

    // Display account information
    displayAccount(&account);

    // Sell stock
    sellStock(&account, &stock1, 3);
    sellStock(&account, &stock2, 5);

    // Display account information
    displayAccount(&account);

    return 0;
}
```

